import React, { useState } from 'react';
import { Line } from 'react-chartjs-2';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend,
  Filler
} from 'chart.js';
import { products, stores, generateStockData, stockTrends } from '../../data/stockPulseData';

ChartJS.register(
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend,
  Filler
);

function StockPulse() {
  const [selectedProduct, setSelectedProduct] = useState(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterBrand, setFilterBrand] = useState('all');
  const [location, setLocation] = useState('Kathmandu');
  const [results, setResults] = useState([]);
  const [simulationStep, setSimulationStep] = useState(0);
  const [isSearching, setIsSearching] = useState(false);

  const brands = ['all', ...new Set(products.map(p => p.brand))];

  const handleSearch = () => {
    setIsSearching(true);
    setSimulationStep(1);

    setTimeout(() => {
      const filtered = products.filter(p => {
        const matchesSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
          p.brand.toLowerCase().includes(searchTerm.toLowerCase());
        const matchesBrand = filterBrand === 'all' || p.brand === filterBrand;
        return matchesSearch && matchesBrand;
      });

      if (filtered.length > 0) {
        setSimulationStep(2);
        setTimeout(() => {
          setSelectedProduct(filtered[0]);
          const storeResults = stores.map(store => ({
            ...store,
            ...generateStockData(filtered[0].id, store.id),
            product: filtered[0]
          }));
          setResults(storeResults);
          setSimulationStep(3);
          setIsSearching(false);
        }, 1000);
      } else {
        setResults([]);
        setSimulationStep(0);
        setIsSearching(false);
      }
    }, 1000);
  };

  const chartOptions = {
    responsive: true,
    plugins: {
      legend: {
        position: 'top',
        labels: { color: 'white' }
      },
      title: {
        display: true,
        text: 'Stock Trend Analysis (Last 7 Days)',
        color: 'white'
      }
    },
    scales: {
      y: {
        ticks: { color: 'white' },
        grid: { color: 'rgba(255,255,255,0.1)' }
      },
      x: {
        ticks: { color: 'white' },
        grid: { color: 'rgba(255,255,255,0.1)' }
      }
    }
  };

  return (
    <div className="container mx-auto px-4 py-8">
      {/* Project Header */}
      <div className="bg-gradient-to-r from-blue-600 to-cyan-600 rounded-2xl p-8 mb-8 text-white">
        <div className="flex items-center mb-4">
          <span className="text-6xl mr-4">📦</span>
          <div>
            <h1 className="text-4xl font-bold mb-2">StockPulse</h1>
            <p className="text-xl">AI-Powered Smart Inventory & Product Availability Platform</p>
          </div>
        </div>
      </div>

      {/* Problem Statement & System Workflow */}
      <div className="grid md:grid-cols-2 gap-6 mb-8">
        <div className="bg-white/10 backdrop-blur-lg rounded-xl p-6 border border-white/20">
          <h3 className="text-2xl font-bold text-white mb-4">❌ Current System (Manual)</h3>
          <ul className="space-y-3 text-gray-200">
            <li className="flex items-start">
              <span className="mr-2">1.</span>
              <span>Customer visits multiple stores physically to check product availability</span>
            </li>
            <li className="flex items-start">
              <span className="mr-2">2.</span>
              <span>Calls stores individually for stock inquiries</span>
            </li>
            <li className="flex items-start">
              <span className="mr-2">3.</span>
              <span>No real-time stock information or price comparison</span>
            </li>
            <li className="flex items-start">
              <span className="mr-2">4.</span>
              <span>Wastes time and transportation costs</span>
            </li>
            <li className="flex items-start">
              <span className="mr-2">5.</span>
              <span>No predictive insights for future availability</span>
            </li>
          </ul>
        </div>

        <div className="bg-white/10 backdrop-blur-lg rounded-xl p-6 border border-white/20">
          <h3 className="text-2xl font-bold text-white mb-4">✅ Proposed System (Automated)</h3>
          <ul className="space-y-3 text-gray-200">
            <li className="flex items-start">
              <span className="mr-2">1.</span>
              <span>Real-time product search across all nearby stores</span>
            </li>
            <li className="flex items-start">
              <span className="mr-2">2.</span>
              <span>Instant stock availability and price comparison</span>
            </li>
            <li className="flex items-start">
              <span className="mr-2">3.</span>
              <span>AI-powered stock prediction and alerts</span>
            </li>
            <li className="flex items-start">
              <span className="mr-2">4.</span>
              <span>Distance-based store recommendations</span>
            </li>
            <li className="flex items-start">
              <span className="mr-2">5.</span>
              <span>Save time, money, and make informed decisions</span>
            </li>
          </ul>
        </div>
      </div>

      {/* Interactive Simulation */}
      <div className="bg-white/10 backdrop-blur-lg rounded-xl p-8 border border-white/20 mb-8">
        <h2 className="text-3xl font-bold text-white mb-6">🎯 Interactive Simulation</h2>

        {/* Search Interface */}
        <div className="grid md:grid-cols-4 gap-4 mb-6">
          <input
            type="text"
            placeholder="Search product name..."
            className="col-span-2 px-4 py-3 rounded-lg bg-white/20 text-white placeholder-gray-300 border border-white/30 focus:border-blue-400 focus:outline-none"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && handleSearch()}
          />

          <select
            className="px-4 py-3 rounded-lg bg-white/20 text-white border border-white/30 focus:border-blue-400 focus:outline-none"
            value={filterBrand}
            onChange={(e) => setFilterBrand(e.target.value)}
          >
            {brands.map(brand => (
              <option key={brand} value={brand} className="bg-gray-800">
                {brand === 'all' ? 'All Brands' : brand}
              </option>
            ))}
          </select>

          <button
            onClick={handleSearch}
            disabled={isSearching || !searchTerm}
            className="bg-gradient-to-r from-blue-500 to-cyan-500 text-white py-3 px-6 rounded-lg font-semibold hover:shadow-lg transition-all duration-300 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {isSearching ? '🔍 Searching...' : '🔍 Search Stores'}
          </button>
        </div>

        <div className="mb-6">
          <label className="text-white mb-2 block font-semibold">📍 Your Location</label>
          <input
            type="text"
            className="px-4 py-3 rounded-lg bg-white/20 text-white placeholder-gray-300 border border-white/30 w-full md:w-1/2"
            value={location}
            onChange={(e) => setLocation(e.target.value)}
          />
        </div>

        {/* Simulation Steps */}
        {simulationStep > 0 && (
          <div className="bg-blue-900/30 rounded-lg p-6 mb-6">
            <h3 className="text-xl font-bold text-white mb-4">🤖 AI Processing Steps:</h3>
            <div className="space-y-3">
              <div className={`flex items-center ${simulationStep >= 1 ? 'text-green-400' : 'text-gray-400'}`}>
                <span className="mr-3">{simulationStep >= 1 ? '✅' : '⏳'}</span>
                <span>Step 1: Analyzing search query and filters...</span>
              </div>
              <div className={`flex items-center ${simulationStep >= 2 ? 'text-green-400' : 'text-gray-400'}`}>
                <span className="mr-3">{simulationStep >= 2 ? '✅' : '⏳'}</span>
                <span>Step 2: Scanning inventory databases across {stores.length} stores...</span>
              </div>
              <div className={`flex items-center ${simulationStep >= 3 ? 'text-green-400' : 'text-gray-400'}`}>
                <span className="mr-3">{simulationStep >= 3 ? '✅' : '⏳'}</span>
                <span>Step 3: Calculating distances, prices, and stock predictions...</span>
              </div>
            </div>
          </div>
        )}

        {/* Quick Search Suggestions */}
        {!selectedProduct && (
          <div className="bg-purple-900/20 rounded-lg p-4">
            <p className="text-white mb-3 font-semibold">💡 Try searching for:</p>
            <div className="flex flex-wrap gap-2">
              {['iPhone', 'Samsung', 'Nike', 'MacBook', 'Sony'].map(term => (
                <button
                  key={term}
                  onClick={() => { setSearchTerm(term); }}
                  className="bg-white/20 hover:bg-white/30 text-white px-4 py-2 rounded-lg transition-all"
                >
                  {term}
                </button>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* Search Results */}
      {results.length > 0 && selectedProduct && (
        <>
          <div className="bg-white/10 backdrop-blur-lg rounded-xl p-6 border border-white/20 mb-8">
            <h2 className="text-3xl font-bold text-white mb-6">📊 Search Results</h2>

            {/* Selected Product Info */}
            <div className="bg-gradient-to-r from-blue-600/30 to-purple-600/30 rounded-lg p-6 mb-6">
              <div className="flex items-center">
                <span className="text-6xl mr-4">{selectedProduct.image}</span>
                <div>
                  <h3 className="text-2xl font-bold text-white">{selectedProduct.name}</h3>
                  <p className="text-gray-300">Brand: {selectedProduct.brand} | Size: {selectedProduct.size}</p>
                  <p className="text-blue-300 mt-2">Found in {results.filter(r => r.inStock).length} stores</p>
                </div>
              </div>
            </div>

            {/* Store Results */}
            <div className="grid gap-4">
              {results.map((result, idx) => (
                <div
                  key={result.id}
                  className={`border-2 rounded-lg p-6 transition-all duration-300 ${
                    result.inStock
                      ? 'bg-green-900/20 border-green-500/50'
                      : 'bg-red-900/20 border-red-500/50'
                  }`}
                >
                  <div className="flex justify-between items-start flex-wrap gap-4">
                    <div className="flex-1">
                      <div className="flex items-center mb-2">
                        <h4 className="text-xl font-bold text-white mr-3">{result.name}</h4>
                        <span className={`px-3 py-1 rounded-full text-sm font-semibold ${
                          result.inStock ? 'bg-green-500 text-white' : 'bg-red-500 text-white'
                        }`}>
                          {result.inStock ? '✅ In Stock' : '❌ Out of Stock'}
                        </span>
                        {result.trending && (
                          <span className="ml-2 px-3 py-1 rounded-full text-sm font-semibold bg-orange-500 text-white">
                            🔥 Trending
                          </span>
                        )}
                      </div>
                      <p className="text-gray-300">📍 {result.location} • {result.distance} km away</p>
                      <p className="text-gray-300">⭐ Rating: {result.rating}/5.0</p>
                      {result.inStock && (
                        <>
                          <p className="text-white mt-2">
                            <span className="font-semibold">Stock Quantity:</span> {result.quantity} units
                          </p>
                          <p className="text-gray-300">
                            <span className="font-semibold">Estimated Stock Duration:</span> {result.predictedStockDays} days
                          </p>
                          <p className="text-gray-400 text-sm mt-1">
                            Last Updated: {new Date(result.lastUpdated).toLocaleString()}
                          </p>
                        </>
                      )}
                    </div>

                    {result.inStock && (
                      <div className="text-right">
                        <div className="text-3xl font-bold text-white">
                          ₹{result.price.toLocaleString()}
                        </div>
                        {result.discount > 0 && (
                          <div className="text-green-400 font-semibold">
                            {result.discount}% OFF
                          </div>
                        )}
                        <button className="mt-3 bg-blue-500 hover:bg-blue-600 text-white px-6 py-2 rounded-lg font-semibold transition-all">
                          View in Store
                        </button>
                      </div>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* Analytics Dashboard */}
          <div className="grid md:grid-cols-2 gap-6 mb-8">
            <div className="bg-white/10 backdrop-blur-lg rounded-xl p-6 border border-white/20">
              <h3 className="text-2xl font-bold text-white mb-4">📈 Stock Trend Analysis</h3>
              <Line data={stockTrends} options={chartOptions} />
              <p className="text-gray-300 mt-4 text-sm">
                ⚠️ Simulated Data: AI predicts stock will deplete in 7-10 days based on current demand trend
              </p>
            </div>

            <div className="bg-white/10 backdrop-blur-lg rounded-xl p-6 border border-white/20">
              <h3 className="text-2xl font-bold text-white mb-4">🎯 Performance Metrics</h3>
              <div className="space-y-4">
                <div className="bg-blue-900/30 rounded-lg p-4">
                  <div className="text-3xl font-bold text-blue-400">{results.length}</div>
                  <div className="text-gray-300">Stores Scanned</div>
                </div>
                <div className="bg-green-900/30 rounded-lg p-4">
                  <div className="text-3xl font-bold text-green-400">
                    {results.filter(r => r.inStock).length}
                  </div>
                  <div className="text-gray-300">Stores with Stock</div>
                </div>
                <div className="bg-purple-900/30 rounded-lg p-4">
                  <div className="text-3xl font-bold text-purple-400">
                    ₹{Math.min(...results.filter(r => r.inStock).map(r => r.price)).toLocaleString()}
                  </div>
                  <div className="text-gray-300">Best Price Found</div>
                </div>
                <div className="bg-orange-900/30 rounded-lg p-4">
                  <div className="text-3xl font-bold text-orange-400">
                    {Math.min(...results.filter(r => r.inStock).map(r => r.distance))} km
                  </div>
                  <div className="text-gray-300">Nearest Store</div>
                </div>
              </div>
            </div>
          </div>

          {/* Expected Outcomes */}
          <div className="bg-white/10 backdrop-blur-lg rounded-xl p-6 border border-white/20">
            <h3 className="text-2xl font-bold text-white mb-4">✨ Expected Outcomes & Benefits</h3>
            <div className="grid md:grid-cols-3 gap-4">
              <div className="bg-green-900/20 rounded-lg p-4">
                <div className="text-3xl mb-2">⏱️</div>
                <h4 className="font-bold text-white mb-2">Time Saved</h4>
                <p className="text-gray-300 text-sm">85% reduction in search time compared to manual store visits</p>
              </div>
              <div className="bg-blue-900/20 rounded-lg p-4">
                <div className="text-3xl mb-2">💰</div>
                <h4 className="font-bold text-white mb-2">Cost Savings</h4>
                <p className="text-gray-300 text-sm">Average 15% savings through price comparison and discount alerts</p>
              </div>
              <div className="bg-purple-900/20 rounded-lg p-4">
                <div className="text-3xl mb-2">🎯</div>
                <h4 className="font-bold text-white mb-2">Accuracy</h4>
                <p className="text-gray-300 text-sm">95% prediction accuracy for stock availability using AI algorithms</p>
              </div>
            </div>
          </div>
        </>
      )}

      {/* Disclaimer */}
      <div className="mt-8 bg-yellow-900/20 border border-yellow-500/50 rounded-lg p-4">
        <p className="text-yellow-200 text-center">
          ⚠️ <strong>Simulation Mode:</strong> All data shown is sample data for demonstration purposes only.
          Actual implementation would integrate with real store inventory management systems.
        </p>
      </div>
    </div>
  );
}

export default StockPulse;
